"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _require_email(student: Student) -> None:
    if not student.email or not student.email.strip():
        raise ProjectError(
            f"no email for {student.display_name} (id {student.student_id})"
        )


def _format_rows(roster: List[Student]) -> List[str]:
    namewide = max(len(item.display_name) for item in roster)
    sectwide = max(len(item.section) for item in roster)
    return [
        f"{item.display_name:<{namewide}}  {item.section:<{sectwide}}  {item.email}"
        for item in roster
    ]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email in columns, sorted by name."""
    roster = sorted(students, key=lambda item: item.display_name.casefold())
    if not roster:
        raise ProjectError("no students to put on the contact sheet")
    for item in roster:
        _require_email(item)
    return _format_rows(roster)
